using System.Collections;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ChargedBodyEffect", menuName = "Data/Battle/Effects/Hevelius/ChargedBody Effect")]
public class ChargedBodyEffect : Effect
{
	[Header("Charged Body")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private int decreaseChargedBodyAmount;

	[SerializeField]
	private BattleAction playerBattleAction;

	[SerializeField]
	private BattleAction companionBattleAction;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("Description")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private EffectsList effectsList;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return Smart.Format(localizedDescription, GetEffectOrEffectDescription(), purifyAction.GetActionDescription(-1)) + "\n" + base.localizationManager.GetLocalizedThenDecreaseEffect(this, decreaseChargedBodyAmount).UppercaseFirst();
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), GetEffectOrEffectDescription(), purifyAction.GetActionDescription(amount)) + "\n" + base.localizationManager.GetLocalizedThenDecreaseEffect(this, decreaseChargedBodyAmount).UppercaseFirst();
	}

	private string GetEffectOrEffectDescription()
	{
		return Smart.Format(base.localizationManager.GetLocalizedString("TwoEffectsOr"), effectsList.LightShieldEffect.GetEffectName(), effectsList.BarrierEffect.GetEffectName());
	}

	protected override string GetLocalizedDescription()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("WheneverEffectIsAppliedPlayerSentinels");
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		EffectIncreased(effectAmount, effectOwner, source);
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		SpawnSecondVFX(3f);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (!currentCorruptedAnimals.IsAnyEnemyActive())
		{
			return effectAmount;
		}
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		CorruptionStats component = currentCorruptedAnimals.activeCorruptedAnimals.PickRandom().GetComponent<CorruptionStats>();
		component.Purify(effectAmount, null, CorruptionPurifyModifierEnum.NONE, playSFX: true);
		SpawnThirdVFX(GetVFXOwnerPosition(component.gameObject), 3f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(WaitFewFramesToCheckIfEnemyWasDefeated());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		return effectAmount - decreaseChargedBodyAmount;
	}

	private IEnumerator WaitFewFramesToCheckIfEnemyWasDefeated()
	{
		for (int i = 0; i < ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 2; i++)
		{
			yield return new WaitForFixedUpdate();
		}
	}
}
